@app.cell(hide_code=True)
def details_payload(DATA, ORDER, mo):
    import json as _json
    # Build a per-product payload keyed by product name, then install a delegated
    # click handler + modal via a hidden-iframe onload bootstrap (marimo strips
    # <script>, so we inject through the iframe into the parent document).
    _payload = {}
    for _cid in ORDER:
        for _p in DATA["categories"][_cid]["products"]:
            _payload[_p["product"]] = {**_p, "category_label": DATA["categories"][_cid]["label"]}
    _pj = _json.dumps(_payload, ensure_ascii=False)
    _css = (
        ".v3-details{padding:3px 9px;font-size:11px;font-family:'DM Mono',ui-monospace,monospace;"
        "border:1px solid #a5bbbe;background:#fff;color:#0b252f;border-radius:0;cursor:pointer;font-weight:500;"
        "letter-spacing:0.04em;text-transform:uppercase;}"
        ".v3-details:hover{background:#0b252f;color:#f2f1f1;}"
        ".v3-bd{position:fixed;inset:0;background:rgba(11,37,47,0.55);z-index:99999;display:flex;"
        "align-items:flex-start;justify-content:center;padding:40px 20px;overflow-y:auto;font-family:'Plus Jakarta Sans',system-ui,sans-serif;}"
        ".v3-modal{background:#fff;border-radius:0;max-width:780px;width:100%;padding:24px 28px;box-shadow:0px 4px 4px 0px rgba(0,0,0,0.05);}"
        ".v3-modal h2{font-family:'Noto Serif',Georgia,serif;font-weight:600;font-size:1.4rem;letter-spacing:-0.015em;margin:0 0 4px;color:#0b252f;}"
        ".v3-x{float:right;cursor:pointer;background:none;border:1px solid #a5bbbe;border-radius:0;padding:4px 10px;font-size:11px;color:#a5bbbe;}"
        ".v3-sect{margin:16px 0 6px;font-family:'DM Mono',ui-monospace,monospace;font-size:10px;text-transform:uppercase;"
        "letter-spacing:0.08em;color:#0b252f;opacity:0.5;font-weight:600;border-bottom:1px solid #edecec;padding-bottom:4px;}"
        ".v3-row{display:flex;gap:14px;margin:5px 0;font-size:13px;color:#272726;}"
        ".v3-lbl{min-width:96px;color:#a5bbbe;font-family:'DM Mono',ui-monospace,monospace;font-size:11px;}"
        ".v3-val{flex:1;line-height:1.45;}"
        ".v3-pill{display:inline-block;padding:2px 8px;border-radius:0;color:#fff;font-size:11px;font-weight:600;}"
        ".v3-modal ul{margin:4px 0;padding-left:20px;font-size:12.5px;color:#272726;line-height:1.5;}"
        ".v3-modal a{color:#0b252f;text-decoration:none;}.v3-modal a:hover{text-decoration:underline;}"
    )
    _js = r'''
    (function(){
      if (window.__V3_INSTALLED__) { window.__V3_PAYLOAD__ = __PAYLOAD__; return; }
      window.__V3_INSTALLED__ = true; window.__V3_PAYLOAD__ = __PAYLOAD__;
      var esc=function(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});};
      function ocol(sc){return sc==null?'#dcdcda':(sc>=4?'#e86f57':(sc==3?'#f4886f':(sc==2?'#f8ad99':'#f6cabd')));}
      function otext(sc){return '#0b252f';}
      function srcs(a){if(!a||!a.length)return '<span style="color:#a5bbbe">no sources</span>';
        return '<ul>'+a.map(function(s){var u=s&&s.url?s.url:'';var sh=s&&s.shows?s.shows:u;
        return u?'<li><a href="'+esc(u)+'" target="_blank" rel="noopener">'+esc(sh||u)+'</a></li>':'<li>'+esc(sh)+'</li>';}).join('')+'</ul>';}
      function row(l,v){if(v==null||v==='')v='<em style="color:#a5bbbe">n/a</em>';
        return '<div class="v3-row"><span class="v3-lbl">'+esc(l)+'</span><span class="v3-val">'+(typeof v==='string'&&v.indexOf('<')===0?v:esc(v))+'</span></div>';}
      function build(p){
        var o=p.openness||{},ad=p.adoption||{},cap=p.capability||{};
        var h='<div class="v3-bd"><div class="v3-modal"><button class="v3-x">Close \u2715</button>'+
          '<h2>'+esc(p.product||'')+'</h2>'+
          '<div style="font-family:\'DM Mono\',monospace;font-size:11px;color:#a5bbbe;margin-bottom:6px;">'+
            esc(p.org||'')+', '+esc(p.type||'')+', '+esc(p.category_label||'')+
            (o.class?' <span class="v3-pill" style="background:'+ocol(o.score)+';color:'+otext(o.score)+'">'+esc(o.class)+'</span>':'')+'</div>'+
          (p.description?'<div style="font-size:13px;color:#272726;line-height:1.5;margin:8px 0;">'+esc(p.description)+'</div>':'')+
          (p.version_note?'<div style="font-size:11.5px;color:#a5bbbe;line-height:1.45;margin:6px 0;">'+esc(p.version_note)+'</div>':'')+
          '<div class="v3-sect">Openness '+(o.score==null?'n/a':o.score+'/5')+' ('+esc(o.class||'')+')</div>'+
          row('Components',o.components)+row('Why',o.note)+row('Confidence',o.confidence)+
          '<div class="v3-row"><span class="v3-lbl">Sources</span><span class="v3-val">'+srcs(o.sources)+'</span></div>'+
          '<div class="v3-sect">Adoption '+(ad.level==null?'n/a':ad.level+'/5')+'</div>'+
          row('Reach',ad.reach)+row('Signal',ad.signal_type)+row('Detail',ad.note)+row('Confidence',ad.confidence)+
          '<div class="v3-row"><span class="v3-lbl">Sources</span><span class="v3-val">'+srcs(ad.sources)+'</span></div>'+
          '<div class="v3-sect">Capability '+(cap.score==null?'n/a':cap.score+'/5')+'</div>'+
          row('Basis',cap.basis)+row('Value',cap.value)+row('Detail',cap.note)+row('Confidence',cap.confidence)+
          '<div class="v3-row"><span class="v3-lbl">Sources</span><span class="v3-val">'+srcs(cap.sources)+'</span></div>'+
          (p.lineage?('<div class="v3-sect">Lineage</div>'+
            (p.lineage.derived_from&&p.lineage.derived_from.length?row('Derived from',p.lineage.derived_from.join(', ')):'')+
            (p.lineage.curated_with&&p.lineage.curated_with.length?row('Built with',p.lineage.curated_with.join(', ')):'')+
            (p.lineage.trains&&p.lineage.trains.length?row('Trains',p.lineage.trains.join(', ')):'')):'')+
          '</div></div>';
        return h;
      }
      function open(p){var ex=document.getElementById('__v3_modal');if(ex)ex.remove();
        var r=document.createElement('div');r.id='__v3_modal';r.innerHTML=build(p);document.body.appendChild(r);
        var bd=r.querySelector('.v3-bd');function cl(){r.remove();document.removeEventListener('keydown',ek);}
        function ek(e){if(e.key==='Escape')cl();}
        r.querySelectorAll('.v3-x').forEach(function(b){b.addEventListener('click',cl);});
        if(bd)bd.addEventListener('click',function(e){if(e.target===bd)cl();});
        document.addEventListener('keydown',ek);}
      document.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('.v3-details');if(!b)return;
        var p=window.__V3_PAYLOAD__[b.getAttribute('data-pid')];if(p)open(p);});
    })();
    '''
    _full = ("(function(){if(!window.__V3_CSS__){window.__V3_CSS__=true;var s=document.createElement('style');"
             "s.textContent='" + _css.replace("\\", "\\\\").replace("'", "\\'") + "';document.head.appendChild(s);}})();"
             + _js.replace("__PAYLOAD__", _pj))
    _boot = _full.replace("&", "&amp;").replace('"', "&quot;").replace("<", "&lt;")
    mo.Html(
        f'<iframe srcdoc="&lt;!doctype html&gt;&lt;html&gt;&lt;/html&gt;" '
        f'style="display:none;width:0;height:0;border:0;position:absolute" onload="{_boot}"></iframe>'
    )
    return


@app.cell(hide_code=True)
def stages_table(C, DATA, F, ORDER, mo):
    import html as _html  # product display names are contributor-authored
    # The maturity ladder: each category's open ecosystem placed on a 0-5 stage.
    # Only fully-open products count toward a stage (open-ish/closed do not); see
    # docs/guides/gap-analysis.md. Stages + assignments come straight from the payload.
    _DEFS = [
        (0, "Void", "No meaningful open products exist."),
        (1, "Open Experiments", "Open experiments exist, but capability and adoption are both limited."),
        (2, "Emerging Alternatives", "Promising open products exist, but important functionality is missing and adoption is limited."),
        (3, "Viable Alternatives", "Viable open alternatives exist for many use cases."),
        (4, "Competitive Open Ecosystem", "Open solutions are competitive across a broad range of use cases."),
        (5, "Mature Open Ecosystem", "Multiple open solutions are mature, widely adopted, and resilient."),
    ]
    _by_stage = {}
    for _cid in ORDER:
        _sn = (DATA["categories"][_cid].get("stage") or {}).get("num", 0)
        _by_stage.setdefault(_sn, []).append(DATA["categories"][_cid]["label"])

    _rows = []
    for _n, _name, _desc in _DEFS:
        _cats = _by_stage.get(_n, [])
        _cat_html = (
            "".join(
                f'<span style="display:inline-block; font-family:{F["body"]}; font-size:0.82rem; '
                f'color:{C["ink_2"]}; background:{C["paper_2"]}; padding:2px 9px; border-radius:0; '
                f'margin:0 5px 5px 0;">{_l}</span>'
                for _l in _cats
            )
            if _cats
            else f'<span style="font-family:{F["body"]}; font-size:0.82rem; color:{C["ink_3"]}; font-style:italic;">\u2014</span>'
        )
        _rows.append(
            f'<tr style="border-bottom:1px solid {C["rule"]}; vertical-align:top;">'
            f'<td style="padding:14px 14px 14px 0; white-space:nowrap;">'
            f'<span style="display:inline-flex; align-items:center; justify-content:center; width:24px; height:24px; '
            f'box-sizing:border-box; font-family:{F["mono"]}; font-size:0.8rem; font-weight:600; color:{C["ink"]}; '
            f'background:#fff; border:1.5px solid {C["ink"]}; border-radius:50%;">{_n}</span></td>'
            f'<td style="padding:14px 16px 14px 0; font-family:{F["headline"]}; font-size:0.98rem; '
            f'font-weight:600; color:{C["ink"]}; white-space:nowrap;">{_html.escape(str(_name))}</td>'
            f'<td style="padding:14px 16px 14px 0; font-family:{F["body"]}; font-size:0.86rem; '
            f'color:{C["ink_2"]}; line-height:1.45; max-width:300px;">{_desc}</td>'
            f'<td style="padding:14px 0;">{_cat_html}</td>'
            f'</tr>'
        )
    _head = "".join(
        f'<th style="padding:0 16px 8px 0; font-family:{F["mono"]}; font-size:9px; color:{C["ink_3"]}; '
        f'text-transform:uppercase; letter-spacing:0.05em; text-align:left;">{_h}</th>'
        for _h in ["Stage", "", "What it means", "Categories here"]
    )
    mo.Html(
        f'<div style="margin:52px 0 44px;">'
        f'<div style="font-family:{F["mono"]}; font-size:10px; color:{C["accent"]}; '
        f'letter-spacing:0.1em; text-transform:uppercase; margin-bottom:8px;">The maturity ladder</div>'
        f'<h2 style="font-family:{F["headline"]}; font-size:1.6rem; font-weight:600; color:{C["ink"]}; '
        f'margin:0 0 14px; letter-spacing:-0.015em;">How mature is the open ecosystem in each category?</h2>'
        f'<p style="font-family:{F["body"]}; font-size:0.95rem; color:{C["ink_2"]}; margin:0 0 20px; line-height:1.6;">'
        f'Each category sits on a Void \u2192 Mature ladder, scored on the depth of its <em>fully-open</em> '
        f'options; open-weights or source-available products do not count toward a stage, only toward '
        f'flagging an openness gap. A category climbs the ladder as more of its open products clear the combined '
        f'adoption\u00d7capability bar.</p>'
        f'<table style="border-collapse:collapse; width:100%;">'
        f'<thead><tr style="border-bottom:2px solid {C["rule"]};">{_head}</tr></thead>'
        f'<tbody>{"".join(_rows)}</tbody></table></div>'
    )
    return


@app.cell(hide_code=True)
def uncategorized_long_tail(C, DATA, F, mo):
    _lt = DATA["long_tail"]
    _c = _lt["counts"]
    _TC = {"repo": C["border"], "model": C["healthy"], "package": C["warm"], "dataset": C["signal"]}
    _btns = "".join(
        '<button data-ltf="' + _k + '" class="lt-btn' + (' active' if _k == 'all' else '') + '">' + _lab + '</button>'
        for _k, _lab in [("all", "All"), ("repo", "Repos"), ("model", "Models"), ("package", "Packages"), ("dataset", "Datasets")]
    )
    _rows = "".join(
        f'<tr data-lttype="{_t["type"]}" style="border-bottom:1px solid {C["paper_2"]};">'
        f'<td style="padding:7px 10px; font-family:{F["mono"]}; font-size:0.8rem; color:{C["ink"]};">{_t["name"]}</td>'
        f'<td style="padding:7px 10px;"><span style="font-family:{F["mono"]}; font-size:0.64rem; text-transform:uppercase; '
        f'letter-spacing:0.04em; color:{C["ink"]}; background:{_TC.get(_t["type"], C["ink_3"])}; padding:2px 7px; border-radius:0;">{_t["type"]}</span></td>'
        f'<td style="padding:7px 10px; font-family:{F["mono"]}; font-size:0.76rem; color:{C["ink_3"]}; text-align:right; white-space:nowrap;">{_t["usage_label"]}</td>'
        f'<td style="padding:7px 10px; font-family:{F["body"]}; font-size:0.8rem; color:{C["ink_3"]};">{_t["description"]}</td>'
        f'<td style="padding:7px 10px; font-family:{F["mono"]}; font-size:0.66rem; color:{C["rule"]}; text-transform:uppercase; letter-spacing:0.04em;">uncategorized</td>'
        f'</tr>'
        for _t in _lt["top"]
    )
    _head = "".join(
        f'<th style="padding:7px 10px; font-family:{F["mono"]}; font-size:9px; color:{C["ink_3"]}; '
        f'text-transform:uppercase; letter-spacing:0.05em; text-align:{_a};">{_h}</th>'
        for _h, _a in [("Name", "left"), ("Type", "left"), ("Usage", "right"), ("Description", "left"), ("Status", "left")]
    )
    _css = (
        "<style>"
        ".lt-bar .lt-btn{font-family:'DM Mono',ui-monospace,monospace;font-size:11px;border:1px solid #a5bbbe;"
        "background:#fff;color:#0b252f;border-radius:0;padding:4px 11px;cursor:pointer;margin-right:6px;letter-spacing:0.04em;text-transform:uppercase;}"
        ".lt-bar .lt-btn.active{background:#0b252f;color:#f2f1f1;border-color:#0b252f;}"
        ".lt-wrap[data-lttype=repo] tr[data-lttype]:not([data-lttype=repo]){display:none;}"
        ".lt-wrap[data-lttype=model] tr[data-lttype]:not([data-lttype=model]){display:none;}"
        ".lt-wrap[data-lttype=package] tr[data-lttype]:not([data-lttype=package]){display:none;}"
        ".lt-wrap[data-lttype=dataset] tr[data-lttype]:not([data-lttype=dataset]){display:none;}"
        "</style>"
    )
    _js = (
        "(function(){var w=document.querySelector('.lt-wrap');var bar=document.querySelector('.lt-bar');"
        "if(!w||!bar)return;bar.addEventListener('click',function(e){var b=e.target.closest('.lt-btn');if(!b)return;"
        "w.setAttribute('data-lttype',b.getAttribute('data-ltf'));"
        "bar.querySelectorAll('.lt-btn').forEach(function(x){x.classList.toggle('active',x===b);});});})();"
    )
    _enc = _js.replace("&", "&amp;").replace('"', "&quot;").replace("<", "&lt;")
    mo.Html(
        _css
        + f'<div style="margin:48px 0 20px; padding:24px 0 0; border-top:2px solid {C["accent"]};">'
        f'<div style="font-family:{F["mono"]}; font-size:10px; color:{C["accent"]}; '
        f'letter-spacing:0.1em; text-transform:uppercase; margin-bottom:8px;">The long tail</div>'
        f'<h2 style="font-family:{F["headline"]}; font-size:1.6rem; font-weight:600; color:{C["ink"]}; '
        f'margin:0 0 12px; letter-spacing:-0.015em;">{_c["uncategorized"]:,} more products, tracked but not yet scored</h2>'
        f'<p style="font-family:{F["body"]}; font-size:0.95rem; color:{C["ink_2"]}; margin:0 0 16px; line-height:1.6;">'
        f'We track <strong>{_c["total"]:,}</strong> open source AI artifacts in total: '
        f'<strong>{_c["repos"]:,}</strong> repositories, <strong>{_c["models"]:,}</strong> models, and '
        f'<strong>{_c["packages"]:,}</strong> packages. Of the {_c["scored"]} products scored above, '
        f'<strong>{_c["overlap"]}</strong> are drawn from this catalog and <strong>{_c["scored_outside"]}</strong> '
        f'are closed/proprietary products that sit outside it. That leaves <strong>{_c["uncategorized"]:,}</strong> '
        f'catalog artifacts <em>uncategorized</em>. Filter the sample below by type; deep-scoring proceeds by usage rank.</p>'
        f'<div class="lt-bar" style="margin:6px 0 12px;">{_btns}</div>'
        f'<div class="lt-wrap" data-lttype="all">'
        f'<table style="border-collapse:collapse; width:100%;">'
        f'<thead><tr style="border-bottom:2px solid {C["rule"]};">{_head}</tr></thead>'
        f'<tbody>{_rows}</tbody></table></div>'
        f'<p style="font-family:{F["body"]}; font-size:0.82rem; color:{C["ink_3"]}; margin:12px 0 0; line-height:1.5;">'
        f'Usage (stars for repos, downloads for models / datasets / packages) is a discovery signal only, '
        f'not an openness, adoption, or capability score. These rows carry no axis values until researched and sourced.</p>'
        f'</div>'
        + f'<iframe srcdoc="&lt;!doctype html&gt;&lt;html&gt;&lt;/html&gt;" '
        f'style="display:none;width:0;height:0;border:0;position:absolute" onload="{_enc}"></iframe>'
    )
    return


@app.cell(hide_code=True)
def framework_edges(C, FRAMEWORK_EDGES, F, mo):
    _levels = ""
    for _lvl, _gaps in FRAMEWORK_EDGES:
        _items = "".join(
            f'<li style="margin:0 0 9px; line-height:1.5;">'
            f'<strong style="color:{C["ink"]};">{_n}.</strong> '
            f'<span style="color:{C["ink_2"]};">{_d}</span></li>'
            for _n, _d in _gaps
        )
        _levels += (
            f'<div style="margin:0 0 18px;">'
            f'<div style="font-family:{F["mono"]}; font-size:11px; color:{C["accent"]}; '
            f'letter-spacing:0.06em; text-transform:uppercase; margin-bottom:7px;">{_lvl}</div>'
            f'<ul style="font-family:{F["body"]}; font-size:0.88rem; margin:0; padding-left:18px;">{_items}</ul>'
            f'</div>'
        )
    mo.Html(
        f'<div style="margin:48px 0 20px; padding:24px 0 0; border-top:2px solid {C["accent"]};">'
        f'<div style="font-family:{F["mono"]}; font-size:10px; color:{C["accent"]}; '
        f'letter-spacing:0.1em; text-transform:uppercase; margin-bottom:8px;">The map\u2019s edges</div>'
        f'<h2 style="font-family:{F["headline"]}; font-size:1.6rem; font-weight:600; color:{C["ink"]}; '
        f'margin:0 0 12px; letter-spacing:-0.015em;">What\u2019s not on the map yet</h2>'
        f'<p style="font-family:{F["body"]}; font-size:0.95rem; color:{C["ink_2"]}; margin:0 0 18px; line-height:1.6;">'
        f'The Columbia framework treats openness as varying across the whole stack: at the '
        f'<strong>model</strong> level (datasets, code, weights), in the <strong>system</strong> around it '
        f'(infrastructure below, product and UX above), and across <strong>cross-cutting</strong> attributes '
        f'(documentation, licensing, safeguards). The categories above occupy some of those areas; these are the '
        f'ones we have not yet defined as categories. A statement of scope, not a backlog.</p>'
        f'{_levels}'
        f'<p style="font-family:{F["body"]}; font-size:0.82rem; color:{C["ink_3"]}; margin:6px 0 0; line-height:1.5;">'
        f'Licensing, the third cross-cutting attribute, is scored on every product above rather than '
        f'tracked as its own category.</p>'
        f'</div>'
    )
    return


@app.cell(hide_code=True)
def methodology(C, F, mo):
    # Full methodology prose is authored in docs/methodology.md (## Detail),
    # converted from Markdown to HTML at build time and injected as '<p>To create the map, we used both a discovery step (to find the universe) and a more rigorous scoring and enrichment step (to grade each product). The taxonomy we use to categorize products descends directly from the <a href="https://arxiv.org/abs/2405.15802">2024 Columbia Convening on Openness in AI</a>.</p>\n<p>The framework has two levels of analysis:</p>\n<ul>\n<li><strong>Each product</strong> is scored on three axes: <em>openness</em>, <em>adoption</em>, and <em>capability</em>.</li>\n<li><strong>Each category</strong> is rolled up from its products\' scores into a maturity <em>stage</em> from 0 (Void) to 5 (Mature), plus a set of <em>gaps</em> naming what its open ecosystem still lacks.</li>\n</ul>\n<h3>Discovery and scoring</h3>\n<p>The discovery step identifies the universe of candidate products and artifacts; the scoring step enriches and grades a curated subset of them.</p>\n<p>The discovery step draws on large-scale open data from the software supply chain compiled by <a href="https://www.oso.xyz/">Open Source Observer</a>. We seeded it from <a href="https://goodailist.com/">Chip Huyen\'s Good AI List</a>, a catalog of AI-focused repositories, then broadened it through analysis of the <a href="https://huggingface.co/">Hugging Face Hub</a>, the <a href="https://huggingface.co/open-llm-leaderboard">Open LLM Leaderboard</a>, the <a href="https://incidentdatabase.ai/">AI Incident Database</a>, package registries and SBOMs, and academic and industry publications. From these sources we assembled approximately 24,853 candidate products, including 15,375 GitHub repositories, 6,428 models and datasets, and 2,823 package entries. We ranked the candidates by adoption signal (repository stars, package and model downloads, and related measures) and enriched the most prominent first.</p>\n<p>The scoring step enriched and graded 472 products in depth: 312 software tools and libraries, 75 models, 65 datasets, and 20 hardware projects, produced by 256 organizations. We organize these products into 16 categories across 3 layers of the stack (model components, product / UX, and infrastructure), though we do not cover the stack exhaustively. The remaining 24,381 artifacts constitute the uncategorized long tail: they are tracked by usage signal but carry no openness, adoption, or capability score until they are researched and cited.</p>\n<h3>The three axes</h3>\n<p>We grade each product on three axes, each answering a different question:</p>\n<ul>\n<li>How open is it? (openness)</li>\n<li>How used is it? (adoption)</li>\n<li>How good is it? (capability)</li>\n</ul>\n<p>The grading is deliberately multi-source. Each axis pulls from a different family (adoption from registries, OpenRouter, and trackers; capability from benchmark leaderboards and papers; openness from primary vendor and repository sources), so no single source determines a product\'s standing.</p>\n<p>Every value also records what the source showed and when we accessed it. Across the scored set this comes to 1,828 primary citations spanning 277 distinct source domains. We excluded any product we could not verify against a primary source rather than estimating it. The result is sourced and auditable: every value is citation-backed and checkable against its primary source. The scores themselves are editorial judgments rather than the output of a deterministic formula, so this is an open trail to follow, not an independently reproducible computation.</p>\n<h4>Axis 1: Openness</h4>\n<p>Openness has two fields. The first, the class, is a categorical label drawn from the <a href="https://isitopen.ai/">Model Openness Framework</a> and OSI license taxonomy (for example <code>open_source</code>, <code>open_weights</code>, <code>open_core</code>, <code>source_available</code>, <code>restricted</code>, <code>gated</code>, <code>documented_only</code>, <code>closed</code>). The class serves as the cross-category normalizer: it is the field to use when positioning a product on an openness spectrum. The second, the score, is a 0–5 grade with a component-level breakdown: weights, data, code, checkpoints, and license for models; license tests for software; access, license, and documentation for datasets.</p>\n<p>The score is graded relative to what is achievable within a product type, so the same number does not carry the same meaning across categories. A pretrained model at 2 is genuinely restricted, because the openness range for models is compressed: open weights typically land near 3, and a 5 requires a fully open pipeline of the Pythia or OLMo kind. A deployment tool at 2 sits elsewhere entirely. The raw 0–5 score should therefore be read as a within-type detail, not as a cross-category coordinate.</p>\n<p>For analysis across the whole stack, we collapse the class vocabulary into three buckets:</p>\n<ul>\n<li>Open: <code>open_source</code>, <code>open</code>, <code>open_core</code>, <code>open_hardware</code></li>\n<li>Open-ish: <code>open_weights</code>, <code>source_available</code>, <code>gated</code>, <code>open_toolchain</code></li>\n<li>Closed: <code>restricted</code>, <code>documented_only</code>, <code>closed</code>, <code>documented</code></li>\n</ul>\n<p>Hardware uses its own openness vocabulary, parallel to the software and model classes: open schematics with an open toolchain (<code>open_hardware</code>); proprietary silicon but an open SDK with public datasheets and retail availability (<code>open_toolchain</code>); public datasheets but proprietary design or firmware (<code>documented</code>); and private or NDA-gated availability (<code>restricted</code>).</p>\n<p>The openness framework descends from the <a href="https://arxiv.org/abs/2405.15802">2024 Columbia Convening on Openness in AI</a> and its <a href="https://arxiv.org/abs/2506.22183">follow-on work</a>, and from the <a href="https://arxiv.org/abs/2403.13784">Model Openness Framework</a>. License, weights, data, and code are each judged separately rather than reduced to a single binary.</p>\n<p>One license scale applies across every product type, as a cap on the score rather than the score itself: OSI or Open-Definition licensing caps at 5, a non-OSI license with no cap on who may use the artifact caps at 4, a bounded commercial license (a monthly-active-user or revenue ceiling, an acceptable-use policy) caps at 3, a license forbidding commercial use outright caps at 2, and an unlicensed or undistributed artifact caps at 1. The 3/2 boundary turns on one question — does the license permit commercial use at all — which is the same line MOF draws at the bottom of its qualifying range. <a href="guides/openness-spectrum.md">The openness spectrum guide</a> has the tier names per ladder and what applying the scale changed.</p>\n<p>MOF and the OSI\'s Open Source AI Definition are both binary — a release is open or it is source-available, with nothing in between. A 0–5 score is a different instrument, and the Columbia Convening catalogues gradient, score, and binary as three legitimate families without picking one. The two are reconciled by a single rule: the <strong>open</strong> bucket requires a license that is open by an external standard (OSI approval for code and weights, the Open Definition for data), so MOF\'s binary line falls between <em>open</em> and <em>open-ish</em>, and levels 4 down to 1 subdivide what MOF treats as one undifferentiated source-available bucket. Two departures from MOF are deliberate and documented in <a href="guides/openness-spectrum.md">the openness spectrum guide</a>: we are stricter than MOF Class III, which does not require training data to be released, and we rank an acceptable-use policy above a commercial cap where MOF excludes both. Primary vendor sources (the blog posts and documentation of Anthropic, Google, OpenAI, Meta, Mistral, NVIDIA, Microsoft, AWS, and others) are cross-checked against the actual LICENSE file in the repository and the model card on the Hugging Face Hub, with arXiv and general web search used to corroborate. The distinction between "open weights" and "open source" is not incidental to the map; it is the distinction the map exists to make.</p>\n<h4>Axis 2: Adoption</h4>\n<p>Adoption is graded 1–5 and measures real usage (downloads, active users, and deployments) rather than repository popularity. GitHub stars are treated as a weak last-resort signal and never raise a product above level 3.</p>\n<p>The sources differ by product type. For repositories we use GitHub stars, forks, and developer activity; for models and datasets, Hugging Face downloads and likes; for packages, registry download statistics (PyPI via pypistats.org, pepy.tech, and pypi.org, together with npm). Relative usage across models is estimated from OpenRouter\'s per-model token-share leaderboard. For the large closed consumer surfaces, where first-party usage figures are unavailable, we rely on traffic and monthly-active-user trackers such as Business of Apps and DemandSage.</p>\n<p>We recognize that adoption metrics can be gamed or manipulated, and welcome community feedback on the sources and methods used to compute them.</p>\n<h4>Axis 3: Capability</h4>\n<p>Capability is graded 1–5, and each grade records its basis: a community benchmark where one exists, a structured feature grid where none does, or null where capability is not a meaningful axis for the product type.</p>\n<p>Capability means different things for a model, a tool, and a dataset, so capability grades are comparable <em>within</em> a category and not across categories. Benchmark evidence is drawn from Artificial Analysis (its Intelligence Index), LMArena / Chatbot Arena, Epoch AI (including FrontierMath, GPQA Diamond, and SWE-bench), Scale\'s SEAL leaderboards, Vals AI, LLM-Stats, and the EleutherAI evaluation-harness lineage behind the Open LLM Leaderboard. For specialized categories we use domain benchmarks (for example ANN-Benchmarks and Qdrant\'s published figures for vector databases, and SWE-bench aggregators for coding agents), and in some cases we return to the original arXiv papers for methodology and reported results.</p>\n<h3>Maturity stages</h3>\n<p>We place every category on a maturity stage from 0 (Void) to 5 (Mature), computed deterministically from its products\' scores, in two steps: first we score each product\'s maturity, then we read the category\'s stage off how many of its open products are mature. The ladder measures <strong>fully-open-pipeline maturity</strong> specifically: only products in the fully-<code>open</code> bucket count toward a stage. Open-weights models never advance a stage, no matter how capable or widely adopted, so the stage is a verdict on the genuinely-open ecosystem rather than on open AI in general.</p>\n<p><strong>Step 1: the product maturity score.</strong> Each product receives a single score on a 1–5 scale, a per-category weighted blend of its adoption and capability grades:</p>\n<pre><code>score = (w_adopt · adoption + w_cap · capability) / (w_adopt + w_cap)\n</code></pre>\n<p>The weights vary by category, because the two axes do not matter equally everywhere: adoption is weighted more heavily for end-user surfaces such as UI &amp; API (0.7 adoption to 0.3 capability), and capability more heavily for the model categories (0.3 to 0.7); the two weights sum to one. A product with no adoption signal at all receives no score and is left out of its category\'s stage. Datasets are scored on the same two axes as everything else, but each axis means something specific to a corpus: adoption is verified download volume, graded against bands set one order of magnitude below the package bands (a multi-terabyte corpus is pulled per training run, not per CI job; benchmark datasets, whose small files are pulled by harnesses on every run, keep the standard bands), and capability is training value — how good the models built on the corpus are, read from controlled ablations and downstream-model evidence rather than from the corpus in isolation. Training value here is deliberately narrow: it means performance under frontier-style, largely English and benchmark-driven evaluation, and does not capture a corpus\'s consent and licensing basis, documentation quality, or language coverage, which are openness and scope concerns rather than capability. A low capability score therefore marks a corpus as not the current pick for that objective, not as low quality. A product is <strong>mature</strong> only when its blended score reaches 4.5 of 5, a deliberately demanding bar: because the map already curates the most prominent products, a lower bar would call almost everything mature.</p>\n<p><strong>Step 2: the category stage.</strong> Only <strong>fully open</strong> products advance a category\'s stage. Open-ish products (open weights, source-available, and the like) are used solely to detect the openness gap below; crediting them would blur the line between open source and open weights that the map exists to draw. The choice is consequential but bounded: counting open-weights models as open would move only three categories, all in the model layer — base/pretrained models (Stage 3→5), fine-tuned/chat models (2→3), and edge hardware (3→4) — and would leave every infrastructure and tooling verdict unchanged. The open-model verdict should therefore be read as a deliberately strict reading of a few model categories, not a sweeping claim about the whole stack. The ladder measures the health of the genuinely open ecosystem:</p>\n<ul>\n<li><strong>Stage 5: Mature Open Ecosystem.</strong> Four or more mature fully open products: redundant and resilient.</li>\n<li><strong>Stage 4: Competitive Open Ecosystem.</strong> At least one mature fully open product, but fewer than four.</li>\n<li><strong>Stage 3: Viable Alternatives.</strong> No mature fully open product, but the best fully open option is strong.</li>\n<li><strong>Stage 2: Emerging Alternatives.</strong> No mature fully open product; the best fully open option is promising but limited.</li>\n<li><strong>Stage 1: Open Experiments.</strong> Fully open options exist but are weak on both axes.</li>\n<li><strong>Stage 0: Void.</strong> No usable open option exists.</li>\n</ul>\n<p>The exact cutoffs (four mature products for Stage 5, the 4.5 maturity bar, and best-fully-open score bands of 3.5, 3.0, and 2.0 dividing the lower stages) are deliberate, tunable parameters, reviewed when the scoring rubric or curation density changes materially. Not every category needs to reach Stage 5; redundancy matters more in some parts of the stack than others.</p>\n<h3>Gaps</h3>\n<p>Openness is treated as an axis orthogonal to maturity: a category can hold strong, widely adopted options that are simply not <em>fully</em> open. Each category therefore carries a set of zero or more gaps, derived from the same metrics as the stage:</p>\n<ul>\n<li><strong>Void:</strong> no usable open option exists at all.</li>\n<li><strong>Capability:</strong> the best fully open option is not capable enough to be useful.</li>\n<li><strong>Adoption:</strong> a capable fully open option exists but is under-adopted.</li>\n<li><strong>Maturity:</strong> open options exist, and at least one may be mature, but the ecosystem lacks the depth and redundancy of a mature one (too few mature fully open products).</li>\n<li><strong>Openness:</strong> capable, adopted options exist, but the mature ones are not fully open. This is the orthogonal flag, and it can co-occur with the others.</li>\n<li><strong>Disclosure:</strong> the open products are real and widely used, but the closed frontier\'s own equivalent is undisclosed — labs publish neither their proprietary and licensed data nor their exact recipe. Training data is the clear case: the open corpora are shared (frontier models draw on the same web substrate, and some open corpora were built by the labs themselves), but the proprietary additions and the mixing recipe stay invisible, and that asymmetry is the finding worth surfacing rather than a maturity or adoption shortfall. Unlike the other gaps this flag is declared per category rather than inferred from the scores, so it does not silently toggle on a curation change; it is set on training data and left unset where the open products are the shared public standard the frontier reports against (open evaluation benchmarks). It is orthogonal and can appear at any stage, including Stage 5.</li>\n</ul>\n<p>A fully mature ecosystem carries no gaps, with the one exception that disclosure can still be flagged there: it describes the closed frontier\'s silence, not a shortfall of the open ecosystem. The set is extensible: further gap types, such as maintenance or bus-factor risk, can be added as the underlying signals become available, without changing the staging logic.</p>\n<p>Here are two illustrations:</p>\n<ul>\n<li>The base/pretrained-models and fine-tuned/chat-models categories both carry an openness gap: capable, well-adopted options exist, but the mature ones are not fully open.</li>\n<li>The inference-code category, by contrast, has mature, competitive, well-adopted open source options (vLLM, llama.cpp, SGLang) but few of them; this is a maturity gap, signaling an ecosystem that depends on a small number of projects continuing to do well.</li>\n</ul>\n<p>At present 3 of the 16 categories in the map carry an openness gap. The gap vocabulary is broader than what the current data exercises: in the present scored set the maturity gap is near-ubiquitous, the openness gap appears in only a few model and infrastructure categories, the adoption gap fires rarely, and the void and capability gaps do not fire at all. The unused types are kept in the model because they describe situations the map expects to encounter as coverage grows, not because nothing qualifies for them today by accident.</p>\n<h3>The openness verdict</h3>\n<p>Each category also carries a one-line verdict: which openness tier (open, open-ish, or closed) leads among its strongest products, or <em>competitive</em> when none clearly does. It is a convenience summary on top of the openness scores already described; the per-category counts always show the full open / open-ish / closed mix, so a category that is open in its long tail but closed at the top stays visible.</p>\n<h3>Limitations</h3>\n<p>Several constraints bound the present results and are stated plainly. The scored set is a curated sample of the most prominent products, not a census; the 24,381 artifacts in the long tail are tracked by usage signal only and remain ungraded. Composition and "known-build" relationships are curator-asserted from documentation rather than mined from deployment telemetry. Product descriptions, and therefore keyword-based lookup, are English-centric. The openness class-to-spectrum mapping is the analysts\' editorial judgment, not a law of nature, and some distinctions collapse in it by design. Finally, as noted above, the raw 0–5 openness and capability scores are within-type grades and should not be compared directly across categories.</p>'
    # (numbers already substituted). The scoped <style> below carries the house
    # fonts/colors onto the generated HTML, so the source stays plain Markdown.
    # This <style> also styles the header summary (.v3-sum) links.
    _style = (
        "<style>"
        f".v3-meth, .v3-meth p, .v3-meth li{{font-family:{F['body']};}}"
        f".v3-meth p{{font-size:0.9rem; color:{C['ink_2']}; line-height:1.6; margin:0 0 12px;}}"
        f".v3-meth h3{{font-family:{F['headline']}; font-weight:600; font-size:1.12rem; "
        f"color:{C['ink']}; letter-spacing:-0.01em; margin:28px 0 8px;}}"
        f".v3-meth h4{{font-family:{F['headline']}; font-weight:600; font-size:0.98rem; "
        f"color:{C['ink']}; margin:18px 0 6px;}}"
        f".v3-meth strong{{color:{C['ink']}; font-weight:600;}}"
        ".v3-meth em{font-style:italic;}"
        f".v3-meth a, .v3-sum a{{color:{C['accent']}; text-decoration:underline;}}"
        ".v3-meth ul{margin:6px 0 14px; padding-left:20px;}"
        f".v3-meth li{{font-size:0.9rem; color:{C['ink_2']}; line-height:1.55; margin:0 0 5px;}}"
        ".v3-meth table{border-collapse:collapse; width:100%; margin:10px 0 18px;}"
        f".v3-meth th{{font-family:{F['mono']}; font-size:9px; text-transform:uppercase; "
        f"letter-spacing:0.05em; color:{C['ink_3']}; text-align:left; padding:7px 12px 7px 0; "
        f"border-bottom:2px solid {C['rule']};}}"
        f".v3-meth td{{font-size:0.84rem; color:{C['ink_2']}; padding:7px 12px 7px 0; "
        f"border-bottom:1px solid {C['rule']}; vertical-align:top; line-height:1.45;}}"
        f".v3-meth code{{font-family:{F['mono']}; font-size:0.82rem; background:{C['paper_2']}; padding:1px 5px;}}"
        f".v3-meth pre{{font-family:{F['mono']}; font-size:0.8rem; color:{C['ink']}; "
        f"background:{C['paper_2']}; padding:12px 16px; margin:8px 0 16px; overflow-x:auto; line-height:1.5;}}"
        ".v3-meth pre code{background:none; padding:0;}"
        "</style>"
    )
    mo.Html(
        f'<div style="margin:48px 0 24px; padding:24px 0 0; border-top:2px solid {C["accent"]};">'
        f'<div style="font-family:{F["mono"]}; font-size:10px; color:{C["accent"]}; letter-spacing:0.1em; '
        f'text-transform:uppercase; margin-bottom:10px;">Methodology</div>'
        + _style
        + '<div class="v3-meth">'
        + '<p>To create the map, we used both a discovery step (to find the universe) and a more rigorous scoring and enrichment step (to grade each product). The taxonomy we use to categorize products descends directly from the <a href="https://arxiv.org/abs/2405.15802">2024 Columbia Convening on Openness in AI</a>.</p>\n<p>The framework has two levels of analysis:</p>\n<ul>\n<li><strong>Each product</strong> is scored on three axes: <em>openness</em>, <em>adoption</em>, and <em>capability</em>.</li>\n<li><strong>Each category</strong> is rolled up from its products\' scores into a maturity <em>stage</em> from 0 (Void) to 5 (Mature), plus a set of <em>gaps</em> naming what its open ecosystem still lacks.</li>\n</ul>\n<h3>Discovery and scoring</h3>\n<p>The discovery step identifies the universe of candidate products and artifacts; the scoring step enriches and grades a curated subset of them.</p>\n<p>The discovery step draws on large-scale open data from the software supply chain compiled by <a href="https://www.oso.xyz/">Open Source Observer</a>. We seeded it from <a href="https://goodailist.com/">Chip Huyen\'s Good AI List</a>, a catalog of AI-focused repositories, then broadened it through analysis of the <a href="https://huggingface.co/">Hugging Face Hub</a>, the <a href="https://huggingface.co/open-llm-leaderboard">Open LLM Leaderboard</a>, the <a href="https://incidentdatabase.ai/">AI Incident Database</a>, package registries and SBOMs, and academic and industry publications. From these sources we assembled approximately 24,853 candidate products, including 15,375 GitHub repositories, 6,428 models and datasets, and 2,823 package entries. We ranked the candidates by adoption signal (repository stars, package and model downloads, and related measures) and enriched the most prominent first.</p>\n<p>The scoring step enriched and graded 472 products in depth: 312 software tools and libraries, 75 models, 65 datasets, and 20 hardware projects, produced by 256 organizations. We organize these products into 16 categories across 3 layers of the stack (model components, product / UX, and infrastructure), though we do not cover the stack exhaustively. The remaining 24,381 artifacts constitute the uncategorized long tail: they are tracked by usage signal but carry no openness, adoption, or capability score until they are researched and cited.</p>\n<h3>The three axes</h3>\n<p>We grade each product on three axes, each answering a different question:</p>\n<ul>\n<li>How open is it? (openness)</li>\n<li>How used is it? (adoption)</li>\n<li>How good is it? (capability)</li>\n</ul>\n<p>The grading is deliberately multi-source. Each axis pulls from a different family (adoption from registries, OpenRouter, and trackers; capability from benchmark leaderboards and papers; openness from primary vendor and repository sources), so no single source determines a product\'s standing.</p>\n<p>Every value also records what the source showed and when we accessed it. Across the scored set this comes to 1,828 primary citations spanning 277 distinct source domains. We excluded any product we could not verify against a primary source rather than estimating it. The result is sourced and auditable: every value is citation-backed and checkable against its primary source. The scores themselves are editorial judgments rather than the output of a deterministic formula, so this is an open trail to follow, not an independently reproducible computation.</p>\n<h4>Axis 1: Openness</h4>\n<p>Openness has two fields. The first, the class, is a categorical label drawn from the <a href="https://isitopen.ai/">Model Openness Framework</a> and OSI license taxonomy (for example <code>open_source</code>, <code>open_weights</code>, <code>open_core</code>, <code>source_available</code>, <code>restricted</code>, <code>gated</code>, <code>documented_only</code>, <code>closed</code>). The class serves as the cross-category normalizer: it is the field to use when positioning a product on an openness spectrum. The second, the score, is a 0–5 grade with a component-level breakdown: weights, data, code, checkpoints, and license for models; license tests for software; access, license, and documentation for datasets.</p>\n<p>The score is graded relative to what is achievable within a product type, so the same number does not carry the same meaning across categories. A pretrained model at 2 is genuinely restricted, because the openness range for models is compressed: open weights typically land near 3, and a 5 requires a fully open pipeline of the Pythia or OLMo kind. A deployment tool at 2 sits elsewhere entirely. The raw 0–5 score should therefore be read as a within-type detail, not as a cross-category coordinate.</p>\n<p>For analysis across the whole stack, we collapse the class vocabulary into three buckets:</p>\n<ul>\n<li>Open: <code>open_source</code>, <code>open</code>, <code>open_core</code>, <code>open_hardware</code></li>\n<li>Open-ish: <code>open_weights</code>, <code>source_available</code>, <code>gated</code>, <code>open_toolchain</code></li>\n<li>Closed: <code>restricted</code>, <code>documented_only</code>, <code>closed</code>, <code>documented</code></li>\n</ul>\n<p>Hardware uses its own openness vocabulary, parallel to the software and model classes: open schematics with an open toolchain (<code>open_hardware</code>); proprietary silicon but an open SDK with public datasheets and retail availability (<code>open_toolchain</code>); public datasheets but proprietary design or firmware (<code>documented</code>); and private or NDA-gated availability (<code>restricted</code>).</p>\n<p>The openness framework descends from the <a href="https://arxiv.org/abs/2405.15802">2024 Columbia Convening on Openness in AI</a> and its <a href="https://arxiv.org/abs/2506.22183">follow-on work</a>, and from the <a href="https://arxiv.org/abs/2403.13784">Model Openness Framework</a>. License, weights, data, and code are each judged separately rather than reduced to a single binary.</p>\n<p>One license scale applies across every product type, as a cap on the score rather than the score itself: OSI or Open-Definition licensing caps at 5, a non-OSI license with no cap on who may use the artifact caps at 4, a bounded commercial license (a monthly-active-user or revenue ceiling, an acceptable-use policy) caps at 3, a license forbidding commercial use outright caps at 2, and an unlicensed or undistributed artifact caps at 1. The 3/2 boundary turns on one question — does the license permit commercial use at all — which is the same line MOF draws at the bottom of its qualifying range. <a href="guides/openness-spectrum.md">The openness spectrum guide</a> has the tier names per ladder and what applying the scale changed.</p>\n<p>MOF and the OSI\'s Open Source AI Definition are both binary — a release is open or it is source-available, with nothing in between. A 0–5 score is a different instrument, and the Columbia Convening catalogues gradient, score, and binary as three legitimate families without picking one. The two are reconciled by a single rule: the <strong>open</strong> bucket requires a license that is open by an external standard (OSI approval for code and weights, the Open Definition for data), so MOF\'s binary line falls between <em>open</em> and <em>open-ish</em>, and levels 4 down to 1 subdivide what MOF treats as one undifferentiated source-available bucket. Two departures from MOF are deliberate and documented in <a href="guides/openness-spectrum.md">the openness spectrum guide</a>: we are stricter than MOF Class III, which does not require training data to be released, and we rank an acceptable-use policy above a commercial cap where MOF excludes both. Primary vendor sources (the blog posts and documentation of Anthropic, Google, OpenAI, Meta, Mistral, NVIDIA, Microsoft, AWS, and others) are cross-checked against the actual LICENSE file in the repository and the model card on the Hugging Face Hub, with arXiv and general web search used to corroborate. The distinction between "open weights" and "open source" is not incidental to the map; it is the distinction the map exists to make.</p>\n<h4>Axis 2: Adoption</h4>\n<p>Adoption is graded 1–5 and measures real usage (downloads, active users, and deployments) rather than repository popularity. GitHub stars are treated as a weak last-resort signal and never raise a product above level 3.</p>\n<p>The sources differ by product type. For repositories we use GitHub stars, forks, and developer activity; for models and datasets, Hugging Face downloads and likes; for packages, registry download statistics (PyPI via pypistats.org, pepy.tech, and pypi.org, together with npm). Relative usage across models is estimated from OpenRouter\'s per-model token-share leaderboard. For the large closed consumer surfaces, where first-party usage figures are unavailable, we rely on traffic and monthly-active-user trackers such as Business of Apps and DemandSage.</p>\n<p>We recognize that adoption metrics can be gamed or manipulated, and welcome community feedback on the sources and methods used to compute them.</p>\n<h4>Axis 3: Capability</h4>\n<p>Capability is graded 1–5, and each grade records its basis: a community benchmark where one exists, a structured feature grid where none does, or null where capability is not a meaningful axis for the product type.</p>\n<p>Capability means different things for a model, a tool, and a dataset, so capability grades are comparable <em>within</em> a category and not across categories. Benchmark evidence is drawn from Artificial Analysis (its Intelligence Index), LMArena / Chatbot Arena, Epoch AI (including FrontierMath, GPQA Diamond, and SWE-bench), Scale\'s SEAL leaderboards, Vals AI, LLM-Stats, and the EleutherAI evaluation-harness lineage behind the Open LLM Leaderboard. For specialized categories we use domain benchmarks (for example ANN-Benchmarks and Qdrant\'s published figures for vector databases, and SWE-bench aggregators for coding agents), and in some cases we return to the original arXiv papers for methodology and reported results.</p>\n<h3>Maturity stages</h3>\n<p>We place every category on a maturity stage from 0 (Void) to 5 (Mature), computed deterministically from its products\' scores, in two steps: first we score each product\'s maturity, then we read the category\'s stage off how many of its open products are mature. The ladder measures <strong>fully-open-pipeline maturity</strong> specifically: only products in the fully-<code>open</code> bucket count toward a stage. Open-weights models never advance a stage, no matter how capable or widely adopted, so the stage is a verdict on the genuinely-open ecosystem rather than on open AI in general.</p>\n<p><strong>Step 1: the product maturity score.</strong> Each product receives a single score on a 1–5 scale, a per-category weighted blend of its adoption and capability grades:</p>\n<pre><code>score = (w_adopt · adoption + w_cap · capability) / (w_adopt + w_cap)\n</code></pre>\n<p>The weights vary by category, because the two axes do not matter equally everywhere: adoption is weighted more heavily for end-user surfaces such as UI &amp; API (0.7 adoption to 0.3 capability), and capability more heavily for the model categories (0.3 to 0.7); the two weights sum to one. A product with no adoption signal at all receives no score and is left out of its category\'s stage. Datasets are scored on the same two axes as everything else, but each axis means something specific to a corpus: adoption is verified download volume, graded against bands set one order of magnitude below the package bands (a multi-terabyte corpus is pulled per training run, not per CI job; benchmark datasets, whose small files are pulled by harnesses on every run, keep the standard bands), and capability is training value — how good the models built on the corpus are, read from controlled ablations and downstream-model evidence rather than from the corpus in isolation. Training value here is deliberately narrow: it means performance under frontier-style, largely English and benchmark-driven evaluation, and does not capture a corpus\'s consent and licensing basis, documentation quality, or language coverage, which are openness and scope concerns rather than capability. A low capability score therefore marks a corpus as not the current pick for that objective, not as low quality. A product is <strong>mature</strong> only when its blended score reaches 4.5 of 5, a deliberately demanding bar: because the map already curates the most prominent products, a lower bar would call almost everything mature.</p>\n<p><strong>Step 2: the category stage.</strong> Only <strong>fully open</strong> products advance a category\'s stage. Open-ish products (open weights, source-available, and the like) are used solely to detect the openness gap below; crediting them would blur the line between open source and open weights that the map exists to draw. The choice is consequential but bounded: counting open-weights models as open would move only three categories, all in the model layer — base/pretrained models (Stage 3→5), fine-tuned/chat models (2→3), and edge hardware (3→4) — and would leave every infrastructure and tooling verdict unchanged. The open-model verdict should therefore be read as a deliberately strict reading of a few model categories, not a sweeping claim about the whole stack. The ladder measures the health of the genuinely open ecosystem:</p>\n<ul>\n<li><strong>Stage 5: Mature Open Ecosystem.</strong> Four or more mature fully open products: redundant and resilient.</li>\n<li><strong>Stage 4: Competitive Open Ecosystem.</strong> At least one mature fully open product, but fewer than four.</li>\n<li><strong>Stage 3: Viable Alternatives.</strong> No mature fully open product, but the best fully open option is strong.</li>\n<li><strong>Stage 2: Emerging Alternatives.</strong> No mature fully open product; the best fully open option is promising but limited.</li>\n<li><strong>Stage 1: Open Experiments.</strong> Fully open options exist but are weak on both axes.</li>\n<li><strong>Stage 0: Void.</strong> No usable open option exists.</li>\n</ul>\n<p>The exact cutoffs (four mature products for Stage 5, the 4.5 maturity bar, and best-fully-open score bands of 3.5, 3.0, and 2.0 dividing the lower stages) are deliberate, tunable parameters, reviewed when the scoring rubric or curation density changes materially. Not every category needs to reach Stage 5; redundancy matters more in some parts of the stack than others.</p>\n<h3>Gaps</h3>\n<p>Openness is treated as an axis orthogonal to maturity: a category can hold strong, widely adopted options that are simply not <em>fully</em> open. Each category therefore carries a set of zero or more gaps, derived from the same metrics as the stage:</p>\n<ul>\n<li><strong>Void:</strong> no usable open option exists at all.</li>\n<li><strong>Capability:</strong> the best fully open option is not capable enough to be useful.</li>\n<li><strong>Adoption:</strong> a capable fully open option exists but is under-adopted.</li>\n<li><strong>Maturity:</strong> open options exist, and at least one may be mature, but the ecosystem lacks the depth and redundancy of a mature one (too few mature fully open products).</li>\n<li><strong>Openness:</strong> capable, adopted options exist, but the mature ones are not fully open. This is the orthogonal flag, and it can co-occur with the others.</li>\n<li><strong>Disclosure:</strong> the open products are real and widely used, but the closed frontier\'s own equivalent is undisclosed — labs publish neither their proprietary and licensed data nor their exact recipe. Training data is the clear case: the open corpora are shared (frontier models draw on the same web substrate, and some open corpora were built by the labs themselves), but the proprietary additions and the mixing recipe stay invisible, and that asymmetry is the finding worth surfacing rather than a maturity or adoption shortfall. Unlike the other gaps this flag is declared per category rather than inferred from the scores, so it does not silently toggle on a curation change; it is set on training data and left unset where the open products are the shared public standard the frontier reports against (open evaluation benchmarks). It is orthogonal and can appear at any stage, including Stage 5.</li>\n</ul>\n<p>A fully mature ecosystem carries no gaps, with the one exception that disclosure can still be flagged there: it describes the closed frontier\'s silence, not a shortfall of the open ecosystem. The set is extensible: further gap types, such as maintenance or bus-factor risk, can be added as the underlying signals become available, without changing the staging logic.</p>\n<p>Here are two illustrations:</p>\n<ul>\n<li>The base/pretrained-models and fine-tuned/chat-models categories both carry an openness gap: capable, well-adopted options exist, but the mature ones are not fully open.</li>\n<li>The inference-code category, by contrast, has mature, competitive, well-adopted open source options (vLLM, llama.cpp, SGLang) but few of them; this is a maturity gap, signaling an ecosystem that depends on a small number of projects continuing to do well.</li>\n</ul>\n<p>At present 3 of the 16 categories in the map carry an openness gap. The gap vocabulary is broader than what the current data exercises: in the present scored set the maturity gap is near-ubiquitous, the openness gap appears in only a few model and infrastructure categories, the adoption gap fires rarely, and the void and capability gaps do not fire at all. The unused types are kept in the model because they describe situations the map expects to encounter as coverage grows, not because nothing qualifies for them today by accident.</p>\n<h3>The openness verdict</h3>\n<p>Each category also carries a one-line verdict: which openness tier (open, open-ish, or closed) leads among its strongest products, or <em>competitive</em> when none clearly does. It is a convenience summary on top of the openness scores already described; the per-category counts always show the full open / open-ish / closed mix, so a category that is open in its long tail but closed at the top stays visible.</p>\n<h3>Limitations</h3>\n<p>Several constraints bound the present results and are stated plainly. The scored set is a curated sample of the most prominent products, not a census; the 24,381 artifacts in the long tail are tracked by usage signal only and remain ungraded. Composition and "known-build" relationships are curator-asserted from documentation rather than mined from deployment telemetry. Product descriptions, and therefore keyword-based lookup, are English-centric. The openness class-to-spectrum mapping is the analysts\' editorial judgment, not a law of nature, and some distinctions collapse in it by design. Finally, as noted above, the raw 0–5 openness and capability scores are within-type grades and should not be compared directly across categories.</p>'
        + '</div></div>'
    )
    return


@app.cell(hide_code=True)
def next_steps(C, F, mo):
    _items = [
        ("Category editors.",
         "Stand up a steward for each category who owns its definition, the product "
         "list, the openness / adoption / capability inputs, the sourcing of reviews, "
         "and the open-vs-closed calls. Editors should have no direct stake in the "
         "products they rank."),
        ("Community contributions.",
         "Three GitHub-routed pathways: add a review on a product, submit a new "
         "project, or join as an editor, all version-controlled in the "
         "ecosystem-mapping repo."),
        ("Deeper coverage.",
         "Score the uncategorized long tail by usage rank, and broaden adoption "
         "signals beyond downloads to agent- and skill-marketplace activity."),
        ("Living methodology.",
         "Keep the taxonomy light: a clean 3\u20134 sentence description per "
         "product, with categories that products can migrate between as the stack "
         "evolves."),
    ]
    _lis = "".join(
        f'<li style="margin:0 0 10px; line-height:1.5;"><strong>{_h}</strong> {_b}</li>'
        for _h, _b in _items
    )
    mo.Html(
        f'<div style="padding-top:24px; border-top:1px solid {C["rule"]}; margin:8px 0 16px;">'
        f'<div style="font-family:{F["mono"]}; font-size:10px; color:{C["accent"]}; '
        f'letter-spacing:0.1em; text-transform:uppercase; margin-bottom:8px;">Roadmap</div>'
        f'<h2 style="font-family:{F["headline"]}; font-size:1.5rem; font-weight:600; '
        f'color:{C["ink"]}; margin:0 0 14px;">Next steps</h2>'
        f'<p style="font-family:{F["body"]}; font-size:0.9rem; color:{C["ink_2"]}; '
        f'line-height:1.6; margin:0 0 12px;">This map is a first pass, not a finished '
        f'product. Depth comes from editors, the domain experts who own a category and '
        f'keep it honest, not from more in-house passes.</p>'
        f'<ul style="font-family:{F["body"]}; font-size:0.88rem; color:{C["ink_2"]}; '
        f'margin:6px 0 0; padding-left:18px;">{_lis}</ul></div>'
    )
    return


